import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.BGkQCay2.js";const h=JSON.parse('{"title":"Platform Support","description":"","frontmatter":{},"headers":[],"relativePath":"guide/platform-support.md","filePath":"guide/platform-support.md"}'),o={name:"guide/platform-support.md"};function n(s,e,d,l,p,c){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="platform-support" tabindex="-1">Platform Support <a class="header-anchor" href="#platform-support" aria-label="Permalink to &quot;Platform Support&quot;">​</a></h1><p>Platform support has two separate dimensions: whether the compiler can check a program for a target, and whether the bundled runtime, linker, native I/O, and optional backends can build and run there. Do not treat a target triple or a successful source check as proof of full runtime support.</p><h2 id="current-support-matrix" tabindex="-1">Current support matrix <a class="header-anchor" href="#current-support-matrix" aria-label="Permalink to &quot;Current support matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Current documentation status</th><th>Notes</th></tr></thead><tbody><tr><td>macOS ARM64</td><td>Primary development platform</td><td>Local fused compile/run and the representative native comptime corpus are characterized; release certification still requires a retained clean-host artifact.</td></tr><tr><td>macOS x86_64</td><td>Experimental</td><td>Requires independent runtime validation on the target machine.</td></tr><tr><td>Linux x86_64 / ARM64</td><td>Experimental</td><td>Structural target checks and release lanes exist; retain green native artifacts on each exact release host before promoting support.</td></tr><tr><td>FreeBSD</td><td>Experimental</td><td>Not validated in this documentation pass.</td></tr><tr><td>Windows</td><td>Experimental</td><td>Toolchain and runtime integration are not validated in this documentation pass.</td></tr><tr><td>WASM</td><td>Experimental</td><td>Limited compiler and library surface; do not assume native-runtime parity.</td></tr><tr><td>iOS and other Apple targets</td><td>Planned or experimental</td><td>A target entry alone does not provide a supported runtime port.</td></tr></tbody></table><h2 id="building-from-source" tabindex="-1">Building from source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from source&quot;">​</a></h2><p>The most reliable workflow is to build the compiler from the repository and check a small program first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/release/vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/01_basics/hello_world.vx</span></span></code></pre></div><p>The exact native dependencies depend on the compiler checkout and host platform. Follow the repository build instructions and record the toolchain versions when reporting a failure.</p><h2 id="fusion-and-native-link-boundary" tabindex="-1">Fusion and native-link boundary <a class="header-anchor" href="#fusion-and-native-link-boundary" aria-label="Permalink to &quot;Fusion and native-link boundary&quot;">​</a></h2><p><code>vex lint</code> validates source semantics but does not execute LLVM object emission, native linking, or the produced program. <code>vex compile</code> and <code>vex run</code> rehydrate target-selected VexArch sources from the compiler&#39;s embedded VRI; they do not rebuild or link a separate runtime artifact. Platform certification must still exercise the requested target&#39;s native support pack, linker, system ABI and execution path.</p><h2 id="reporting-platform-results" tabindex="-1">Reporting platform results <a class="header-anchor" href="#reporting-platform-results" aria-label="Permalink to &quot;Reporting platform results&quot;">​</a></h2><p>Include:</p><ul><li>operating-system version and architecture;</li><li>compiler version and repository revision;</li><li>Rust, LLVM, linker, and C toolchain versions where relevant;</li><li>the exact <code>vex lint</code>, <code>vex compile</code>, or <code>vex run</code> command;</li><li>whether the failure occurred during source checking, VRI target selection, fused codegen, native linking, or execution.</li></ul><p>Platform claims should be updated only after the relevant path has been tested on that platform.</p>`,14)])])}const m=t(o,[["render",n]]);export{h as __pageData,m as default};
